static func height(p: Vector2, t: float, wave_height: float, wave_length: float, wave_speed: float) -> float:
	var d1 := Vector2(1.0, 0.3).normalized()
	var d2 := Vector2(-0.4,
	    1.0).normalized()
	var k1 := TAU / wave_length
	var k2 := TAU / (0.6 * wave_length)
	var p1 := k1 * (d1.dot(p) - wave_speed * t)
	var p2 := k2 * (d2.dot(p) - 0.8 * wave_speed * t)
	return wave_height * (sin(p1) + 0.6 * sin(p2))

func set_clock(t: float) -> void:
	clock = t
	var mat := water.material_override as ShaderMaterial
	mat.set_shader_parameter("wave_clock", t)
	mat.set_shader_parameter("wave_height", wave_height)
	mat.set_shader_parameter("wave_length", wave_length)
	mat.set_shader_parameter("wave_speed", wave_speed)
	for f in floaters:
	    var p := Vector2(f.position.x, f.position.z)
